import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { dataCatalogCertificationsList, dataCatalogMetricsList } from 'products/data_catalog/frontend/generated/api'
import { DataCatalogCertificationApi, DataCatalogMetricApi } from 'products/data_catalog/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biStartersLogicValues {
    metrics: DataCatalogMetricApi[]
    metricsLoading: boolean
    sources: DataCatalogCertificationApi[]
    sourcesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biStartersLogicActions {
    loadMetrics: () => any
    loadMetricsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadMetricsSuccess: (
        metrics: DataCatalogMetricApi[],
        payload?: any
    ) => {
        metrics: DataCatalogMetricApi[]
        payload?: any
    }
    loadSources: () => any
    loadSourcesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSourcesSuccess: (
        sources: DataCatalogCertificationApi[],
        payload?: any
    ) => {
        sources: DataCatalogCertificationApi[]
        payload?: any
    }
}

export type biStartersLogicType = MakeLogicType<biStartersLogicValues, biStartersLogicActions>

export const biStartersLogic = kea<biStartersLogicType>([
    path(['products', 'business_intelligence', 'biStartersLogic']),
    loaders({
        metrics: [
            [] as DataCatalogMetricApi[],
            {
                loadMetrics: async (): Promise<DataCatalogMetricApi[]> => {
                    const metrics: DataCatalogMetricApi[] = []
                    try {
                        for (let offset = 0; metrics.length < 3; offset += 50) {
                            const response = await dataCatalogMetricsList(String(teamLogic.values.currentTeamId), {
                                limit: 50,
                                offset,
                            })
                            metrics.push(
                                ...response.results.filter(
                                    (metric) =>
                                        metric.status === 'approved' &&
                                        !metric.is_drifted &&
                                        metric.definition_kind === 'HogQLQuery'
                                )
                            )
                            if (!response.next) {
                                break
                            }
                        }
                    } catch {
                        // Optional starters must not block the worksheet library when the catalog is unavailable.
                    }
                    return metrics.slice(0, 3)
                },
            },
        ],
        sources: [
            [] as DataCatalogCertificationApi[],
            {
                loadSources: async (): Promise<DataCatalogCertificationApi[]> => {
                    const sources: DataCatalogCertificationApi[] = []
                    try {
                        for (let offset = 0; sources.length < 3; offset += 50) {
                            const response = await dataCatalogCertificationsList(
                                String(teamLogic.values.currentTeamId),
                                {
                                    limit: 50,
                                    offset,
                                }
                            )
                            sources.push(...response.results.filter((source) => source.status === 'certified'))
                            if (!response.next) {
                                break
                            }
                        }
                    } catch {
                        // Catalog suggestions are optional; the library remains usable without them.
                    }
                    return sources.slice(0, 3)
                },
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadMetrics()
        actions.loadSources()
    }),
])
